async (page) => {
  const base = new URL(page.url()).origin;
  const evidence = 'docs/verification/investigation-2026-10-24';
  const assert = (value, message) => { if (!value) throw new Error(message); };
  const saved = () => page.evaluate(() => JSON.parse(localStorage.getItem('scenecaptions.profile.v1')));
  await page.goto(base);
  await page.evaluate(() => localStorage.removeItem('scenecaptions.profile.v1'));
  await page.reload();
  await page.setViewportSize({ width: 1440, height: 1100 });
  await page.waitForFunction(() => document.querySelector('video').readyState >= 1);
  const track = await (await page.request.get(base + '/research/demo-captions.json')).json();
  const apple = track.cues.find(cue => cue.original_text === '[APPLE THUDS]');
  await page.getByRole('button', { name: 'Rich', exact: true }).click();
  await page.getByText('Caption readability', { exact: true }).click();
  await page.getByLabel('Text size', { exact: true }).selectOption('extra-large');
  assert(await page.getByLabel('Level of detail', { exact: false }).inputValue() === '3', 'Readability must retain unfinished detail');
  assert(await page.locator('.readability').getAttribute('open') !== null, 'Readability remains open');
  assert((await saved()).detail === 2, 'Readability must not save unfinished content');
  await page.getByLabel('Position on the video', { exact: true }).selectOption('top');
  await page.locator('.cue-row').nth(track.cues.indexOf(apple)).click();
  await page.waitForFunction(text => document.querySelector('.caption-lines')?.textContent === text, apple.grid['2-2']);
  const previewButton = page.getByRole('button', { name: 'Preview this cue in the video', exact: true });
  await previewButton.click();
  await page.waitForFunction(text => document.querySelector('.caption-lines')?.textContent === text, apple.grid['3-3']);
  assert((await saved()).detail === 2, 'Preview must not persist candidate settings');
  assert(await page.locator('video').evaluate(el => el.paused), 'Preview pauses playback');
  await page.getByRole('button', { name: 'Return to saved settings', exact: true }).waitFor({ state: 'hidden', timeout: 8000 });
  assert(await page.locator('.caption-lines').textContent() === apple.grid['2-2'], 'Preview timeout restores applied wording');
  assert(await page.getByLabel('Level of detail', { exact: false }).inputValue() === '3', 'Timeout retains unfinished draft');
  await previewButton.click();
  await page.getByRole('button', { name: 'Return to saved settings', exact: true }).click();
  assert(await page.locator('.caption-lines').textContent() === apple.grid['2-2'], 'Manual return restores applied wording');
  await page.getByRole('button', { name: 'Apply preferences', exact: true }).click();
  assert((await saved()).detail === 3 && (await saved()).size === 'extra-large', 'Apply retains readability and saves content');
  await page.getByRole('button', { name: 'Essential', exact: true }).click();
  await page.getByRole('button', { name: 'Apply preferences', exact: true }).click();
  await page.locator('.cue-row').first().click();
  await page.waitForFunction(text => document.querySelector('.caption-lines')?.textContent === text, track.cues[0].grid['1-1']);
  await page.getByRole('button', { name: 'Show original', exact: true }).click();
  assert(await previewButton.isDisabled(), 'Original override has priority over preview');
  await page.getByLabel('I agree to record this demo’s player interactions locally.').check();
  await page.getByRole('button', { name: 'Start rehearsal', exact: false }).click();
  async function exportSession(name) {
    const waiting = page.waitForEvent('download');
    await page.getByRole('button', { name: 'Export rehearsal JSON', exact: false }).click();
    const download = await waiting;
    await download.saveAs(evidence + '/exports/' + name);
    let text = '';
    for await (const chunk of await download.createReadStream()) text += chunk.toString();
    return JSON.parse(text);
  }
  const initial = await exportSession('initial-original-state.json');
  assert(initial.events.some(event => event.type === 'original' && event.enabled && event.elapsed_ms === 0), 'Initial original override must be recorded');
  assert(initial.final_original_override === true, 'Export includes final original flag');
  await page.getByRole('button', { name: 'Stop recording', exact: true }).click();
  const first = await exportSession('stopped-first.json');
  const second = await exportSession('stopped-second.json');
  assert(first.elapsed_ms === second.elapsed_ms, 'Stopped elapsed duration must not keep increasing');
  await page.getByRole('button', { name: 'Original on', exact: true }).click();
  await page.getByRole('button', { name: 'Rich', exact: true }).click();
  await previewButton.click();
  await page.evaluate(() => scrollTo({ top: 0, behavior: 'instant' }));
  await page.screenshot({ path: evidence + '/screenshots/preview-desktop.png' });
  await page.getByRole('button', { name: 'Return to saved settings', exact: true }).click();
  await page.setViewportSize({ width: 390, height: 844 });
  assert(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth), 'No narrow-screen overflow');
  await page.screenshot({ path: evidence + '/screenshots/player-mobile.png', fullPage: true });
  return { passed: ['draft survives readability changes', 'readability panel stays open', 'temporary on-video preview, timeout and manual return', 'preview never persists', 'detail maximum', 'original override priority', 'initial/final original state exported', 'stopped duration frozen', 'narrow layout'] };
}
